#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#define x_BYTE_ unsigned char
#define x_BOOL_ int 
#define x_TRUE_  -1
#define x_FALSE_  0

#define SDIMG_GET_WORD(ptr,is_intel) (     \
    (is_intel) ? (ptr[0]) | (ptr[1]<<8)    \
               : (ptr[0]<<8) | (ptr[1])   )\

#define SDIMG_GET_DWORD(ptr,is_intel) (                                 \
    (is_intel) ? (ptr[0]) | (ptr[1]<<8) | (ptr[2]<<16) | (ptr[3]<<24)   \
               : (ptr[0]<<24) | (ptr[1]<<16) | (ptr[2]<<8) | (ptr[3])  )\

#define SDIMG_READ_WORD( out_var, file )   \
    out_var  = fgetc(file) << 8;           \
    out_var |= fgetc(file);                \
    if( out_var<0x0000 || 0xFFFF<out_var ) { out_var=-1; }


typedef enum  _SDImgPromptEncoding {
    SDImgPromptEncoding_ASCII,
    SDImgPromptEncoding_UTF8,
    SDImgPromptEncoding_UTF16BE,
    SDImgPromptEncoding_UTF16LE
} SDImgPromptEncoding;

typedef struct _SDImgPrompt SDImgPrompt;
struct         _SDImgPrompt {
    char                *buffer;
    int                  buffer_size;
    int                  buffer_needed_size;
    SDImgPromptEncoding  encoding;
};

/**
 * @brief Detects the encoding of a prompt.
 *
 * This function analyzes a buffer to determine the encoding of a prompt.
 * It counts the null characters in even and odd positions and checks if
 * the prompt is ASCII, UTF-8, UTF-16BE, or UTF-16LE encoded.
 *
 * @param buffer       Pointer to the buffer containing the prompt data.
 * @param buffer_size  Size of the buffer in bytes.
 *
 * @return The encoding of the SD image prompt. Possible values are:
 *         - SDImgPromptEncoding_ASCII
 *         - SDImgPromptEncoding_UTF8
 *         - SDImgPromptEncoding_UTF16BE
 *         - SDImgPromptEncoding_UTF16LE
 */
static
SDImgPromptEncoding sdimg_detect_encoding(const void *buffer, int buffer_size ) {
    const unsigned char *ptr, *end;
    int null_count_even=0, null_count_odd=0, consecutive_null=0, ascii=1;
    
    /* count null characters in even & odd positions */
    ptr = buffer;  end = (ptr + buffer_size);
    while( ptr<end && consecutive_null<2 ) {
        consecutive_null = 0;
        if( *ptr>=128   ) { ascii=0; }
        if( *ptr++ == 0 ) { null_count_even++; consecutive_null++; }
        if( *ptr>=128   ) { ascii=0; }
        if( *ptr++ == 0 ) { null_count_odd++ ; consecutive_null++; }
    }
    if( null_count_even<=1 && null_count_odd<=1 ) {
        return ascii ? SDImgPromptEncoding_ASCII : SDImgPromptEncoding_UTF8;
    } else if (null_count_even > null_count_odd) {
        return SDImgPromptEncoding_UTF16BE;
    } else {
        return SDImgPromptEncoding_UTF16LE;
    }
}

/*---------------------------------- JPG ----------------------------------*/

/**
 * @brief Reads the markers at the beginning of each data segment in a JPG file.
 *
 * This function reads the input file byte by byte until it finds a valid
 * segment marker. Segment markers in JPG format start with the byte 0xFF,
 * followed by a byte other than 0xFF.
 *
 * @param file  Pointer to the JPG file to be read.
 * @return
 *     The value of the read marker if found successfully,
 *     or JPEG_ERROR in case of error or end of file.
 */
static
int sdimg_read_jpg_marker( FILE *file ) {
    enum { JPEG_ERROR=-1 };
    int hi_byte, lo_byte;
    do { hi_byte=fgetc(file); } while( hi_byte!=EOF && hi_byte!=0xFF );
    if( hi_byte==EOF ) { return JPEG_ERROR; }
    do { lo_byte = fgetc(file); } while( lo_byte!=EOF && lo_byte==0xFF );
    if( lo_byte==EOF ) { return JPEG_ERROR; }
    return (hi_byte << 8) | lo_byte;
}


static
x_BOOL_ sdimg_search_tiff_dir( int  *out_offset,
                               int  *out_count,
                               int   tag_to_find,
                               FILE *file,
                               int   is_intel,
                               int   seek_offset )
{
    static const int ENTRY_SIZE = 12; x_BYTE_ dir_buffer[ 48 ];
    const int max_entry_count = sizeof(dir_buffer) / ENTRY_SIZE;
    x_BYTE_ *ptr; int tag, entry_count, total_entries;
    
    if( seek_offset>=0 && fseek(file, seek_offset, SEEK_SET)!=0 ) {
        return x_FALSE_;
    }
    if( fread( dir_buffer, 2, 1, file ) != 1 ) {
        return x_FALSE_;
    }
    total_entries = SDIMG_GET_WORD(dir_buffer,is_intel);    
    while( total_entries>0 ) {
        entry_count    = (total_entries<max_entry_count) ? total_entries : max_entry_count;
        total_entries -= entry_count;
        ptr            = dir_buffer;
        if( fread( ptr, ENTRY_SIZE, entry_count, file ) != entry_count ) {
            return x_FALSE_;
        }
        while( entry_count-->0 ) {
            tag = SDIMG_GET_WORD(ptr,is_intel); ptr+=4;
            if( tag != tag_to_find ) { ptr+=8; }
            else {
                (*out_count)  = SDIMG_GET_DWORD(ptr,is_intel); ptr+=4;
                (*out_offset) = SDIMG_GET_DWORD(ptr,is_intel); ptr+=4;
                return x_TRUE_;
            }
        }
    }
    return x_FALSE_;
}

static
x_BOOL_ sdimg_read_prompt_from_tiff( SDImgPrompt *prompt, FILE *file ) {
    static const x_BYTE_ IntelHeader[4]    = { 0x49, 0x49, 0x2A, 0x00 };
    static const x_BYTE_ MotorolaHeader[4] = { 0x4D, 0x4D, 0x00, 0x2A };
    static const int TAG_EXIF_OFFSET  = 0x8769;
    static const int TAG_USER_COMMENT = 0x9286;
    static const int CHAR_CODE_SIZE = 8; /* char code designation = 8 bytes */
    x_BOOL_ is_intel;
    x_BYTE_ header[8], *ptr;
    int ifd0_offset, exif_offset, usercomment_offset, count, read_size;
    const long tiff_start = ftell( file );

    /* identify tiff header */
    fread( ptr=header, sizeof(header), 1, file );
    if( memcmp(ptr,IntelHeader,sizeof(IntelHeader)) == 0 ) {
        is_intel = x_TRUE_; /* intel format (little-endian) */
    }
    else if( memcmp(ptr,MotorolaHeader,sizeof(MotorolaHeader)) == 0 ) {
        is_intel = x_FALSE_; /* motorola format (big-endian) */
    }
    else { return x_FALSE_; /* unknown format */ }
    
    /* get the offset of IFD (Image File Directory) */
    ptr+=4; ifd0_offset = SDIMG_GET_DWORD( ptr, is_intel ); 

    /* find UserComment */
    if( !sdimg_search_tiff_dir( &exif_offset, &count, TAG_EXIF_OFFSET,
                                file, is_intel, tiff_start+ifd0_offset ) ) {
        return x_FALSE_;
    }
    if( !sdimg_search_tiff_dir( &usercomment_offset, &count, TAG_USER_COMMENT,
                                file, is_intel, tiff_start+exif_offset ) ) {
        return x_FALSE_;
    }
    
    /* read UserComment */
    read_size  = count<prompt->buffer_size ? count : prompt->buffer_size;
    read_size -= CHAR_CODE_SIZE;
    fseek( file, tiff_start + usercomment_offset + CHAR_CODE_SIZE, SEEK_SET );
    fread( prompt->buffer, read_size, 1, file );
    prompt->buffer[read_size] = prompt->buffer[read_size+1] = '\0';
    prompt->encoding = sdimg_detect_encoding( prompt->buffer, read_size );
    return x_TRUE_;
}
    
static
x_BOOL_ sdimg_read_prompt_from_jpg( SDImgPrompt *prompt, FILE *file ) {
    enum  {
        JPEG_ERROR          = -1,
        ENTROPY_FAKE_MARKER = 0xFF00,
        MARKER_SOI          = 0xFFD8,
        MARKER_EOI          = 0xFFD9,
        MARKER_DRI          = 0xFFDD,
        MARKER_APP0         = 0xFFE0,
        MARKER_APP1,MARKER_APP2,MARKER_APP3,MARKER_APP4,
        MARKER_RST0         = 0xFFD0,
        MARKER_RST1,MARKER_RST2,MARKER_RST3,MARKER_RST4,
        MARKER_RST5,MARKER_RST6,MARKER_RST7
    };
    static const x_BYTE_ EXIF_HEADER[6] = { 0x45, 0x78, 0x69, 0x66, 0x00, 0x00 };
    x_BYTE_ header[6]; int marker, size;
    
    /* marker search */
    marker = 0; while( marker!=JPEG_ERROR && marker!=MARKER_EOI ) {
        marker = sdimg_read_jpg_marker( file );
        /* printf("Marker 0x%X\n", marker); */
        switch( marker ) {
            
            case MARKER_APP1:
                fseek( file, 2, SEEK_CUR ); /* <-- skip size */
                fread( header, sizeof(header), 1, file );
                if( memcmp( EXIF_HEADER, header, sizeof(header) )==0 ) {
                    return sdimg_read_prompt_from_tiff( prompt, file );
                }
                else { marker=JPEG_ERROR; }
                break;
                
            case MARKER_DRI:
                fseek(file, 2, SEEK_CUR);
                break;
                
            case MARKER_SOI:
            case MARKER_EOI:
            case MARKER_RST0: case MARKER_RST1: case MARKER_RST2:
            case MARKER_RST3: case MARKER_RST4: case MARKER_RST5:
            case MARKER_RST6: case MARKER_RST7:
            case ENTROPY_FAKE_MARKER:
            case JPEG_ERROR:
                break;
    
            default:
                SDIMG_READ_WORD( size, file );
                if( size>=2 ) { fseek(file, size-2, SEEK_CUR); }
                else          { marker=JPEG_ERROR; }
                break;
        }
    }
    return x_FALSE_;
}

/*---------------------------------- PNG ----------------------------------*/

static
x_BOOL_ sdimg_read_text_chunk(char       *buffer,
                              int         buffer_size,
                              const char *key,
                              FILE       *file)
{
    #define CHUNK_HEADER_SIZE 8 /* CHUNK_LENGTH + CHUNK_TYPE */
#   define CHUNK_CRC_SIZE     4

    x_BYTE_ chunk_header[CHUNK_HEADER_SIZE];
    int chunk_size = -1, read_size = -1;
    x_BYTE_ *chunk_type = &chunk_header[4];
    x_BOOL_ error, key_found, chunk_found;
    
    /* the buffer must have enough space to store the 'chunk key' */
    /* because when the "tEXt" chunk is loaded, both the key and  */
    /* value are loaded into the buffer.                          */
    const int key_size = strlen(key)+1;
    if( buffer_size<key_size ) {
        return x_FALSE_;
    }
    
    error = key_found = x_FALSE_;
    while( !error && !key_found )
    {
        /* search for a "tEXt" chunk */
        chunk_found = x_FALSE_;
        while( !error && !chunk_found ) {
            if( fread( chunk_header, sizeof(chunk_header), 1, file ) ) {
                chunk_size = (chunk_header[0] << 24) |
                             (chunk_header[1] << 16) |
                             (chunk_header[2] <<  8) |
                             (chunk_header[3]      ) ;
                chunk_type = &chunk_header[4];
                chunk_found = memcmp(chunk_type,"tEXt",4)==0;
                if( !chunk_found ) {
                    fseek( file, chunk_size+CHUNK_CRC_SIZE, SEEK_CUR );
                }
            }
            else { error = x_TRUE_; }
        }
        /* if the "tEXt" chunk has found              */
        /* then verify if the chunk has the right key */
        if( chunk_found ) {
            if( chunk_size>key_size ) {
                read_size = chunk_size<buffer_size ? chunk_size : buffer_size;
                key_found =
                    fread( buffer, read_size, 1, file )==1 &&
                    memcmp( buffer, key, key_size )==0;
                if( key_found ) {
                    memmove( buffer, buffer+key_size, read_size-key_size );
                    memset( buffer+(read_size-key_size), 0, key_size );
                }                    
            }
        }
    }
    return key_found ? chunk_size : 0;
}

static
x_BOOL_ sdimg_has_png_signature( FILE *file ) {
    static const x_BYTE_ SIGNATURE[] = {137, 80, 78, 71, 13, 10, 26, 10};
    x_BYTE_ buffer[sizeof(SIGNATURE)];
    
    return
        fread(buffer, sizeof(buffer), 1, file) &&
        memcmp(buffer, SIGNATURE, sizeof(SIGNATURE))==0;    
}

static
x_BOOL_ sdimg_read_prompt_from_png( SDImgPrompt *prompt, FILE *file ) {
    
    if( !sdimg_has_png_signature(file) ){
        return x_FALSE_;
    }
    prompt->buffer_needed_size = sdimg_read_text_chunk(prompt->buffer,
                                                       prompt->buffer_size,
                                                       "parameters",
                                                       file );
    return prompt->buffer_needed_size>0;
}

/*-------------------------------- HELPERS --------------------------------*/

static
x_BOOL_ sdimg_read_prompt( SDImgPrompt *prompt, FILE *file ) {
    
    if( sdimg_has_png_signature(file) ) {
        prompt->buffer_needed_size =
            sdimg_read_text_chunk( prompt->buffer,
                                   prompt->buffer_size,
                                   "parameters",
                                   file );
        return prompt->buffer_needed_size>0;
    } else {
        fseek( file, 0, SEEK_SET );
        return sdimg_read_prompt_from_jpg( prompt, file );
    }
}

static
SDImgPrompt * sdimg_allocate_prompt( int buffer_size ) {
    SDImgPrompt *prompt; char *ptr;
    ptr = calloc(1, sizeof(SDImgPrompt) + buffer_size );
    prompt = (SDImgPrompt *)ptr;
    prompt->buffer      = ptr + sizeof(SDImgPrompt);
    prompt->buffer_size = buffer_size;
    return prompt;
}


#undef x_FALSE_
#undef x_TRUE_
#undef x_BOOL_
#undef x_BYTE_
